import{_ as o,l as i,o as e,c as n,v as r,p as l,x as t,d as c,i as d,S as F}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"跨时钟域 FIFO","description":"","frontmatter":{"title":"跨时钟域 FIFO","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/async-fifo-cdc.md","filePath":"cs/async-fifo-cdc.md","lastUpdated":1789023840000}'),E={name:"cs/async-fifo-cdc.md"};function h(f,a,p,A,m,u){const s=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="跨时钟域-fifo" tabindex="-1">跨时钟域 FIFO <a class="header-anchor" href="#跨时钟域-fifo" aria-label="Permalink to &quot;跨时钟域 FIFO&quot;">​</a></h1><div class="epigraph"><p>两个无关时钟之间不能直接采样多比特总线；用格雷码指针的异步 FIFO，让空满比较只过同步器，数据停在 RAM 里。</p><footer>—— 据 Cummings, Simulation and Synthesis Techniques for Asynchronous FIFO Design, SNUG 2002；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p><a href="/cs/reset-strategy">上一课</a>要求每域各自同步复位。组成课的<a href="/cs/clock-domain">时钟域</a>已禁止直接跨域打多比特。<a href="/cs/reset-strategy">复位</a>只解决控制初值。缺口是<strong>数据</strong>：生产者时钟写、消费者时钟读，如何不丢、不重复、不亚稳。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单比特过两级同步器。总线的各位亚稳窗口不同，会采到从未出现过的组合值。异步 FIFO：双端口 RAM，写指针在写时钟域递增，读指针在读时钟域递增。把指针编成<a href="/cs/gray-code">格雷码</a>再同步到对域，空/满在对域比较。缺口不是再定义亚稳，而是这套指针协议。</p><p>深度与几乎满/几乎空阈值是实现参数。本课钉格雷指针 + 同步，不把每家 IP 的参数表抄来。</p><h3 id="fifo-不是「加几个-ff-打一拍」" tabindex="-1">FIFO 不是「加几个 FF 打一拍」 <a class="header-anchor" href="#fifo-不是「加几个-ff-打一拍」" aria-label="Permalink to &quot;FIFO 不是「加几个 FF 打一拍」&quot;">​</a></h3><p>打一拍只在<strong>同一时钟</strong>下是流水线。跨域打一拍仍是非法多比特采样。把 CDC 理解成「插入寄存器就能过 STA」，STA 若把跨域当同步路径还会误报/漏报。应用 <code>set_clock_groups -asynchronous</code> 一类约束，功能正确靠 FIFO 结构。</p><p><span class="marginnote">Cummings SNUG 2002 异步 FIFO 是经典参考。Gray 码保证相邻指针只变 1 比特，同步后要么旧值要么新值，不会跳成第三种计数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写域：二进制写指针转格雷，写入指针寄存器，同步到读域。读域对称。满：同步过来的读指针与本地写指针比较（需多 1 位区分满空）。RAM 地址用二进制指针。复位：两域都回到空，且<a href="/cs/reset-strategy">同步释放</a>之后才能开始比指针。</p>',11)),(e(),l(F,null,{default:t(()=>[d(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20WCLK%5B%22%E5%86%99%E6%97%B6%E9%92%9F%E5%9F%9F%22%5D%20--%3E%20RAM%5B%22%E5%8F%8C%E5%8F%A3%20RAM%22%5D%0A%20%20RCLK%5B%22%E8%AF%BB%E6%97%B6%E9%92%9F%E5%9F%9F%22%5D%20--%3E%20RAM%0A%20%20WCLK%20--%3E%20WG%5B%22%E5%86%99%E6%8C%87%E9%92%88%E6%A0%BC%E9%9B%B7%22%5D%0A%20%20RCLK%20--%3E%20RG%5B%22%E8%AF%BB%E6%8C%87%E9%92%88%E6%A0%BC%E9%9B%B7%22%5D%0A%20%20WG%20--%3E%20SYNCR%5B%22%E5%90%8C%E6%AD%A5%E5%88%B0%E8%AF%BB%E5%9F%9F%22%5D%0A%20%20RG%20--%3E%20SYNCW%5B%22%E5%90%8C%E6%AD%A5%E5%88%B0%E5%86%99%E5%9F%9F%22%5D%0A%20%20SYNCR%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AFPGA%20LUT%20%E5%AE%9E%E7%8E%B0%E8%BF%99%E4%BA%9B%E5%9D%97%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>握手（valid/ready 加同步器）适合稀疏控制；突发数据用 FIFO 更合适。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课 FPGA 有专用异步 FIFO 原语；ASIC 用库 RAM + 本课指针。形式验证可用断言：不满则写、不空则读、数据序保持。那是验证课的用例。DFT 扫描不要把跨域伪路径当成扫描移位违例——约束再次必须匹配。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不解决相位已知的同源分频（可用同步 FIFO 或使能）。不讲 SerDes 弹性缓冲的全部 PCS。不把网络 socket 缓冲当成 CDC。</p><p>后课默认：无关时钟之间的多比特数据走过格雷指针异步 FIFO；单比特才直接两级同步。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>跨域总线禁止直接采样；FIFO 把数据留在 RAM。</li><li>格雷指针只变 1 比特，可安全同步后比空满。</li><li>STA 约束异步组；功能靠结构。</li><li>出处：Cummings, SNUG 2002；Harris and Harris；Gray 码先修。</li></ul>',8))])}const C=o(E,[["render",h]]);export{B as __pageData,C as default};
